	jammer?: JammerSpec | null,
	/**  Mission at start. */
	mission?: Mission_Deserialize | null,
	/**  Held off the board until an event's `spawn_reserve` action brings it in. */
	reserve?: boolean,
	/**  Fraction of fuel at the start, with the fuel model on (default full; format 6). */
