/**  Whose picture a snapshot shows. */
export type Viewer = 
/**  Ground truth for all sides (umpire only). */
{ kind: "white_cell" } | 
/**  The perceived picture of one side. */
{ kind: "side"; side: SideId };

/**  Weapons control status. */
export type Wcs = Wcs_Serialize | Wcs_Deserialize;

/**  Weapons control status. */
export type Wcs_Deserialize = 
/**
 *  Weapons safe: do not fire (self-defence arrives with point defence, Phase 2 slice 9).
 *  Called "hold" before 2026-11-10; files using that word still load.
 */
"safe" | 
/**
 *  Weapons safe: do not fire (self-defence arrives with point defence, Phase 2 slice 9).
 *  Called "hold" before 2026-11-10; files using that word still load.
 */
"hold" | 
/**  Fire only at tracks identified as hostile. */
"tight" | 
/**  Fire at any track not identified as friendly or neutral. */
"free";

/**  Weapons control status. */
export type Wcs_Serialize = 
/**
 *  Weapons safe: do not fire (self-defence arrives with point defence, Phase 2 slice 9).
 *  Called "hold" before 2026-11-10; files using that word still load.
 */
"safe" | 
/**  Fire only at tracks identified as hostile. */
"tight" | 
/**  Fire at any track not identified as friendly or neutral. */
"free";

/**  Weapons expended against effective, for one weapon type of one side. */
export type WeaponRow = {
	side: SideId,
	side_name: string,
	weapon: string,
	/**  Fired in defence (an interceptor at an incoming weapon) rather than at a unit. */
	defensive: boolean,
	fired: number,
	/**  Hit rolls won (for interceptors: threats killed). */
	hits: number,
	/**  Hit rolls lost, or no hit for another reason (lost track, seeker, fuel, adjudicated). */
	missed: number,
	/**  Shot down by the target side's point defence. */
	intercepted: number,
	/**  Units destroyed with this as the last weapon to hit them. */
	kills: number,
};

/**  A side's view of one weapon it tracks. */
export type WeaponTrackView = {
	side: SideId,
	weapon_id: number,
	position: GeoPoint,
	/**  `air` (a missile) or `subsurface` (a torpedo). */
	domain: Domain,
	sensor: SensorKind,
	first_seen_s: number | null,
};

/**  A missile or torpedo in flight, as shown to its own side (and the white cell). */
export type WeaponView = {
	id: number,
	side: SideId,
	weapon: string,
	position: GeoPoint,
	altitude_m: number | null,
	heading_deg: number | null,
	/**  The seeker has acquired its target. */
	homing: boolean,
};

/**  A sense or engage zone of one side. */
export type Zone = Zone_Serialize | Zone_Deserialize;

/**  A sense zone's coverage by its side's sensors, now. */
export type ZoneCoverage = {
	zone: number,
	/**  The sensor types counted (the zone's list, or every type). */
	sensors: SensorKind[],
	/**  Cells inside the zone, row by row from the south-west. */
	cells: CoverageCell[],
	/**  Half a cell's height and width, degrees (to draw the cells). */
	half_lat_deg: number | null,
	half_lon_deg: number | null,
	/**  Covered cells over cells inside the zone (0 when it has none). */
	fraction: number | null,
};

/**  What a zone governs. */
export type ZoneKind = 
/**  Own units inside take the zone's doctrine; contacts gained inside raise an alert. */
"sense" | 
/**  Targets inside are engaged under the zone's weapons control and ROE. */
"engage";

/**  A zone's layer in a choke point's defence: sense far out, engage in the inner layers. */
export type ZoneLayer = "outer" | "middle" | "inner";

/**  A sense or engage zone of one side. */
export type Zone_Deserialize = {
	id: number,
	name: string,
	side: SideId,
	kind: ZoneKind,
	area: Area,
	/**  Fields set here override the unit's own, its group's and its side's. */
	doctrine?: Doctrine_Deserialize,
	/**  The choke point this zone belongs to, if any. */
	choke_point?: string | null,
	/**
	 *  Engage zones: units that engage contacts inside the zone on their own (one round per
	 *  contact per AI period, under the zone's rules).
	 */
	shooters?: UnitId[],
	/**  The zone's layer in a choke point's defence (outer, middle, inner). */
	layer?: ZoneLayer | null,
	/**  Sense zones: the sensor types this layer is for; coverage counts only these (empty: all). */
	sensors?: SensorKind[],
};

/**  A sense or engage zone of one side. */
export type Zone_Serialize = {
	id: number,
	name: string,
	side: SideId,
	kind: ZoneKind,
	area: Area,
	/**  Fields set here override the unit's own, its group's and its side's. */
	doctrine: Doctrine_Serialize,
	/**  The choke point this zone belongs to, if any. */
	choke_point: string | null,
	/**
	 *  Engage zones: units that engage contacts inside the zone on their own (one round per
	 *  contact per AI period, under the zone's rules).
	 */
	shooters: UnitId[],
	/**  The zone's layer in a choke point's defence (outer, middle, inner). */
	layer: ZoneLayer | null,
	/**  Sense zones: the sensor types this layer is for; coverage counts only these (empty: all). */
	sensors: SensorKind[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

